var W=6,H=5,DOOR=(H-1)*W+W-1;
var TY=[['plain',20,2.5,'',3],['dirt',30,4,'',5],['bone',20,5,'🦴',12],['coal',25,9,'🪨',15],['ice',5,7,'❄️',20]];
var CN=['gỗ','bạc','đỏ','tím'],PRICE={drill:150,bomb:250,dyn:400},IT={drill:'🔩',bomb:'💣',dyn:'🧨'},IN={drill:'Khoan',bomb:'Bom',dyn:'Thuốc nổ'};
var MS="data:image/png;base64,";
var PK='<div class="pk"><svg viewBox="0 0 100 100"><line x1="31" y1="72" x2="8" y2="42" stroke="#8a5522" stroke-width="5" stroke-linecap="round"/><path d="M-4 50Q0 35 17 34L15 40Q5 41 1 54Z" fill="#c4c9d4" stroke="#3b3f4a" stroke-width="2" stroke-linejoin="round"/></svg></div>',face=false;
function moleHtml(){var r=cur?cur.dir==='r':face;return '<div class="mole '+(cur?'dig d-'+cur.dir:'idle')+(r?' fr':'')+'"><img class="ms" src="'+MS+'" alt="" draggable="false">'+(cur?PK:'')+'</div>'}
var S,cur=null,mode=null,tt;
function ty(k){for(var i=0;i<TY.length;i++)if(TY[i][0]===k)return TY[i]}
function rndT(){var t=0;TY.forEach(function(a){t+=a[1]});var r=Math.random()*t;for(var i=0;i<TY.length;i++){r-=TY[i][1];if(r<0)return TY[i][0]}return 'dirt'}
function board(){S.grid=[];for(var i=0;i<W*H;i++)S.grid.push((i%W===W-1)?{k:'tun',d:1,l:''}:{k:rndT(),d:0,l:''});S.mole=W-1;cur=null;mode=null}
function load(){try{var d=JSON.parse(localStorage.getItem('daomo4')||'null');if(d&&d.grid&&d.grid.length===W*H)return d}catch(e){}return null}
function save(){try{localStorage.setItem('daomo4',JSON.stringify(S))}catch(e){}}
function toast(m,k,ic){var t=document.getElementById('toast');k=k||'info';
 t.className='toast';t.innerHTML='<span class="ti"></span><span class="tx"></span><i class="tb"></i>';
 t.querySelector('.ti').textContent=ic||(k==='warn'?'⚠️':k==='good'?'✨':'⛏️');t.querySelector('.tx').textContent=m;
 void t.offsetWidth;t.className='toast on '+k;clearTimeout(tt);tt=setTimeout(function(){t.className='toast off '+k},2000)}
function nbs(i){var x=i%W,y=(i/W)|0,o=[];[[1,0],[-1,0],[0,1],[0,-1]].forEach(function(d){var a=x+d[0],b=y+d[1];if(a>=0&&a<W&&b>=0&&b<H)o.push(b*W+a)});return o}
function from(i){var n=nbs(i).filter(function(j){return S.grid[j].d});var r=n.filter(function(j){return j===i+1});return r.length?r[0]:(n.length?n[0]:-1)}
function dur(k){return Math.round(ty(k)[2]*(1+(S.fl-1)*.06))*1000}
function loot(i){var c=S.grid[i],f=S.fl,r=Math.random()*100,p=Math.min(f*.15,6),m=[],x=Math.round(ty(c.k)[4]*(1+(f-1)*.12));
 c.l='';
 if(r<1+p*.3){S.ch[3]++;c.l='c3';m.push('Rương tím!')}
 else if(r<4+p){S.ch[2]++;c.l='c2';m.push('Rương đỏ!')}
 else if(r<11+p){S.ch[1]++;c.l='c1';m.push('Rương bạc!')}
 else if(r<26){S.ch[0]++;c.l='c0';m.push('Rương gỗ')}
 else if(r<32){var n=1+((Math.random()*2)|0);S.dm+=n;c.l='d';m.push('+'+n+'💎')}
 S.xu+=x;m.push('+'+x+'🪙');return m}
function startDig(i){var f=from(i);if(f<0){toast('Chưa tới được ô này — hãy đào từ lối bên cạnh','warn');return}
 var ms=dur(S.grid[i].k),dx=(i%W)-(f%W),dy=((i/W)|0)-((f/W)|0),dir=dx>0?'r':dx<0?'l':dy<0?'u':'d';if(dir==='r')face=true;else if(dir==='l')face=false;cur={i:i,total:ms,end:Date.now()+ms,dir:dir};S.mole=f;render()}
function finish(i,quiet){var c=S.grid[i];c.d=1;var m=loot(i);S.mole=i;
 if(!quiet)toast(m.join(' '),c.l&&c.l[0]==='c'?'good':'info',c.l==='c3'?'👑':c.l&&c.l[0]==='c'?'🎁':c.l==='d'?'💎':'⛏️');return m}
function done(){if(S.grid.every(function(c){return c.d}))toast('Sạch tầng! Vào cửa 🚪 để xuống tầng '+(S.fl+1),'good','🚪');save();render()}
function tap(i){var c=S.grid[i];
 if(c.k==='tun'){if(i===DOOR)descend();return}
 if(c.d)return;
 if(mode){var k=mode,cells;if(S.it[k]<1){toast('Hết vật phẩm — bấm + để mua','warn');mode=null;return render()}
  S.it[k]--;mode=null;
  if(k==='drill')cells=[i];else if(k==='bomb'){cells=[i].concat(nbs(i));var x=i%W,y=(i/W)|0;[[1,1],[-1,1],[1,-1],[-1,-1]].forEach(function(d){var a=x+d[0],b=y+d[1];if(a>=0&&a<W&&b>=0&&b<H)cells.push(b*W+a)})}
  else{cells=[];for(var q=0;q<W-1;q++)cells.push(((i/W)|0)*W+q)}
  var all=[];cells.filter(function(j){return !S.grid[j].d&&S.grid[j].k!=='tun'}).forEach(function(j){all=all.concat(finish(j,true))});
  cur=null;toast('Phá xong! '+all.length+' phần thưởng','good','💥');return done()}
 if(cur){toast('Chuột chũi đang đào — chờ hoặc bấm ⏱ để xong ngay','warn');return}
 startDig(i)}
function skip(){if(!cur)return;var rem=Math.ceil((cur.end-Date.now())/1000),cost=Math.max(1,Math.ceil(rem/12));
 if(S.dm<cost){toast('Không đủ 💎 ('+cost+')','warn');return}S.dm-=cost;fin()}
function fin(){var i=cur.i;cur=null;finish(i);done()}
function descend(){S.fl++;board();toast('Xuống tầng '+S.fl+' — đá cứng hơn, thưởng tốt hơn','good','⬇️');save();render()}
function openCh(k){if(S.ch[k]<1)return;S.ch[k]--;var R=function(a,b){return a+((Math.random()*(b-a+1))|0)},xu=0,dm=0,m=[];
 if(k===0){xu=R(60,120);if(Math.random()<.25)dm=1}else if(k===1){xu=R(150,300);dm=R(1,2)}
 else if(k===2){xu=R(400,700);dm=R(3,5);if(Math.random()<.4){S.it.bomb++;m.push('+1💣')}}
 else{xu=R(1000,1600);dm=R(8,12);S.it.drill++;S.it.dyn++;m.push('+1🔩 +1🧨')}
 S.xu+=xu;S.dm+=dm;toast('Rương '+CN[k]+': +'+xu+'🪙'+(dm?' +'+dm+'💎':'')+' '+m.join(' '),'good','🎁');save();render()}
function buy(k){if(S.xu<PRICE[k]){toast('Không đủ xu ('+PRICE[k]+' 🪙)','warn');return}S.xu-=PRICE[k];S.it[k]++;save();render()}
function bub(){if(!cur)return'';return '<div class="bub"><div class="bar"><i id="bf"></i><span id="bs"></span></div><button class="sk" data-skip="1">⏱ <span id="bc"></span> 💎</button></div>'}
function upd(){if(!cur)return;var rem=Math.max(0,cur.end-Date.now()),p=1-rem/cur.total,f=document.getElementById('bf');if(!f)return;
 f.style.width=(p*100)+'%';document.getElementById('bs').textContent=Math.ceil(rem/1000)+' giây';document.getElementById('bc').textContent=Math.max(1,Math.ceil(rem/12000))}
function render(){var g=document.getElementById('grid');
 if(!g.children.length)for(var i=0;i<W*H;i++){var d=document.createElement('div');d.dataset.i=i;d.setAttribute('role','button');d.tabIndex=0;g.appendChild(d)}
 S.grid.forEach(function(c,i){var e=g.children[i],ok=!c.d&&c.k!=='tun'&&from(i)>=0&&!cur,h='';
  e.className='cell t-'+c.k+(c.d&&c.k!=='tun'?' dug':'')+(ok?' ok':'')+(cur&&cur.i===i?' cur':'')+(i===DOOR?' door':'');
  e.setAttribute('aria-label',c.k==='tun'?(i===DOOR?'Cửa xuống tầng':'Lối đi'):'Ô '+c.k);
  if(i===DOOR)h+='<span>🚪</span><small>Xuống</small>';
  else if(!c.d)h+='<span class="em">'+ty(c.k)[3]+'</span>';
  else if(c.l)h+='<span class="lt">'+(c.l==='d'?'💎':'<span class="ch ch'+c.l[1]+'">📦</span>')+'</span>';
  if(S.mole===i&&i!==DOOR)h+=moleHtml();
  if(cur&&cur.i===i)h+=bub();
  e.innerHTML=h});
 document.getElementById('fl').textContent=S.fl;document.getElementById('xu').textContent=S.xu;document.getElementById('dm').textContent=S.dm;
 document.getElementById('items').innerHTML=['drill','bomb','dyn'].map(function(k){return '<button class="itb'+(mode===k?' on':'')+'" data-it="'+k+'"><b>'+IT[k]+'</b>'+IN[k]+' ×'+S.it[k]+'<i data-buy="'+k+'" title="Mua '+PRICE[k]+' xu">+</i></button>'}).join('');
 document.getElementById('chests').innerHTML=[0,1,2,3].map(function(k){return '<button class="chb" data-ch="'+k+'"'+(S.ch[k]?'':' disabled')+'><b class="ch ch'+k+'">📦</b>Rương '+CN[k]+' ×'+S.ch[k]+'</button>'}).join('');
 document.getElementById('hint').textContent=mode?'Chạm một ô đá để dùng '+IN[mode]+' (phá ngay, không chờ).':'Chạm ô đá cạnh lối đi để đào. Bấm rương để mở. Cửa 🚪 ở góc dưới dẫn xuống tầng sau. Mua: 🔩 150, 💣 250, 🧨 400 xu.';
 upd()}
S=load();if(!S){S={fl:1,xu:100,dm:20,it:{drill:3,bomb:2,dyn:1},ch:[0,0,0,0]};board()}
document.getElementById('grid').addEventListener('click',function(e){if(e.target.closest('[data-skip]'))return skip();var c=e.target.closest('.cell');if(c)tap(+c.dataset.i)});
document.getElementById('grid').addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){var c=e.target.closest('.cell');if(c){e.preventDefault();tap(+c.dataset.i)}}});
document.getElementById('items').addEventListener('click',function(e){var b=e.target.closest('[data-buy]');if(b){e.stopPropagation();return buy(b.dataset.buy)}var t=e.target.closest('[data-it]');if(!t)return;var k=t.dataset.it;if(S.it[k]<1){toast('Hết vật phẩm — bấm + để mua','warn');return}mode=mode===k?null:k;render()});
document.getElementById('chests').addEventListener('click',function(e){var b=e.target.closest('[data-ch]');if(b)openCh(+b.dataset.ch)});
setInterval(function(){if(cur){if(Date.now()>=cur.end)fin();else upd()}},250);
render();
